from collections import deque

class Solution:
    def minimumMoves(self, grid):
        n = len(grid)
        start, target = (0, 0, 0), (n - 1, n - 2, 0)
        q = deque([(start, 0)])
        seen = {start}
        while q:
            (r, c, o), d = q.popleft()
            if (r, c, o) == target:
                return d
            nxt = []
            if o == 0:
                if c + 2 < n and grid[r][c + 2] == 0:
                    nxt.append((r, c + 1, 0))
                if r + 1 < n and grid[r + 1][c] == 0 and grid[r + 1][c + 1] == 0:
                    nxt.append((r + 1, c, 0))
                    if c + 1 < n and grid[r][c + 1] == 0:
                        nxt.append((r, c, 1))
            else:
                if r + 2 < n and grid[r + 2][c] == 0:
                    nxt.append((r + 1, c, 1))
                if c + 1 < n and grid[r][c + 1] == 0 and grid[r + 1][c + 1] == 0:
                    nxt.append((r, c + 1, 1))
                    if r + 1 < n and grid[r + 1][c] == 0:
                        nxt.append((r, c, 0))
            for s in nxt:
                if s not in seen:
                    seen.add(s)
                    q.append((s, d + 1))
        return -1

