#include <queue>
#include <vector>
using namespace std;

class Solution {
public:
    int minimumMoves(vector<vector<int>>& grid) {
        int n = grid.size();
        auto id = [&](int r, int c, int o) { return (r * n + c) * 2 + o; };
        vector<char> vis(n * n * 2, 0);
        queue<array<int, 4>> q;
        q.push({0, 0, 0, 0});
        vis[0] = 1;
        while (!q.empty()) {
            auto [r, c, o, d] = q.front(); q.pop();
            if (r == n - 1 && c == n - 2 && o == 0) return d;
            vector<array<int, 3>> nxt;
            if (o == 0) {
                if (c + 2 < n && !grid[r][c + 2]) nxt.push_back({r, c + 1, 0});
                if (r + 1 < n && !grid[r + 1][c] && !grid[r + 1][c + 1]) {
                    nxt.push_back({r + 1, c, 0});
                    if (!grid[r][c + 1]) nxt.push_back({r, c, 1});
                }
            } else {
                if (r + 2 < n && !grid[r + 2][c]) nxt.push_back({r + 1, c, 1});
                if (c + 1 < n && !grid[r][c + 1] && !grid[r + 1][c + 1]) {
                    nxt.push_back({r, c + 1, 1});
                    if (!grid[r + 1][c]) nxt.push_back({r, c, 0});
                }
            }
            for (auto& [nr, nc, no] : nxt)
                if (!vis[id(nr, nc, no)]) {
                    vis[id(nr, nc, no)] = 1;
                    q.push({nr, nc, no, d + 1});
                }
        }
        return -1;
    }
};

