import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int minimumMoves(int[][] grid) {
        int n = grid.length;
        boolean[][][] vis = new boolean[n][n][2];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{0, 0, 0, 0});
        vis[0][0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], o = cur[2], d = cur[3];
            if (r == n - 1 && c == n - 2 && o == 0) return d;
            if (o == 0) {
                if (c + 2 < n && grid[r][c + 2] == 0) offer(q, vis, r, c + 1, 0, d);
                if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0) {
                    offer(q, vis, r + 1, c, 0, d);
                    if (grid[r][c + 1] == 0) offer(q, vis, r, c, 1, d);
                }
            } else {
                if (r + 2 < n && grid[r + 2][c] == 0) offer(q, vis, r + 1, c, 1, d);
                if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0) {
                    offer(q, vis, r, c + 1, 1, d);
                    if (grid[r + 1][c] == 0) offer(q, vis, r, c, 0, d);
                }
            }
        }
        return -1;
    }

    private void offer(Queue<int[]> q, boolean[][][] vis, int r, int c, int o, int d) {
        if (!vis[r][c][o]) {
            vis[r][c][o] = true;
            q.offer(new int[]{r, c, o, d + 1});
        }
    }
}

