import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int minimumMoves(int[][] grid) {
        int n = grid.length;
        int[][][] dist = new int[n][n][2];
        for (int[][] a : dist) for (int[] b : a) java.util.Arrays.fill(b, -1);
        Queue<int[]> q = new ArrayDeque<>();
        dist[0][0][0] = 0;
        q.offer(new int[]{0, 0, 0});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], o = cur[2], d = dist[r][c][o];
            if (r == n - 1 && c == n - 2 && o == 0) return d;
            if (o == 0) {
                relax(q, dist, r, c + 1, 0, d, c + 2 < n && grid[r][c + 2] == 0);
                boolean canDown = r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0;
                if (canDown) {
                    relax(q, dist, r + 1, c, 0, d, true);
                    relax(q, dist, r, c, 1, d, grid[r][c + 1] == 0);
                }
            } else {
                relax(q, dist, r + 1, c, 1, d, r + 2 < n && grid[r + 2][c] == 0);
                boolean canRight = c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0;
                if (canRight) {
                    relax(q, dist, r, c + 1, 1, d, true);
                    relax(q, dist, r, c, 0, d, grid[r + 1][c] == 0);
                }
            }
        }
        return -1;
    }

    private void relax(Queue<int[]> q, int[][][] dist, int r, int c, int o, int d, boolean ok) {
        if (ok && dist[r][c][o] == -1) {
            dist[r][c][o] = d + 1;
            q.offer(new int[]{r, c, o});
        }
    }
}

